experiments.reproductionCommand:
node --input-type=module <<'NODE'
import * as THREE from 'three';
import { City } from './src/world/city.js';
import { buildHollisData } from './src/content/world_data.js';
import { Rng } from './src/core/rng.js';
import { TIERS } from './src/core/engine.js';
const data=buildHollisData();
const city=new City(data,{},TIERS.medium);
city._mat=k=>new THREE.MeshBasicMaterial({name:k});
city._buildBackdrop(new Rng(data.seed).fork('backdrop'));
const m=city.root.getObjectByName('backdrop:ash'), g=m.geometry;
console.log(JSON.stringify({
  scope:'geometry-only Node execution, material textures replaced, no browser drawing',
  triangles:g.index.count/3, vertices:g.attributes.position.count,
  typedArrayBytes:Object.values(g.attributes).reduce((s,a)=>s+a.array.byteLength,0)+g.index.array.byteLength,
  castShadow:m.castShadow, receiveShadow:m.receiveShadow,
  min:g.boundingBox.min.toArray(), max:g.boundingBox.max.toArray()
}));
NODE
